package com.example.javaanalyzer.ir;

/**
 * One injected dependency of a component.
 *
 * @param memberName field name, or parameter name for constructor / setter injection
 * @param type the type exactly as declared at the injection point
 * @param origin LOMBOK when the injecting constructor is generated by Lombok
 * @param qualifier value of a qualifier annotation such as {@code @Qualifier}, or null
 * @param beanType the type of the injected beans, with framework wrappers such as {@code
 *     Optional<Foo>} or {@code List<Foo>} removed; equal to {@code type} when there is no wrapper
 * @param multipleBeans true when every matching bean is injected, e.g. {@code List<Foo>}
 */
public record InjectionModel(
    InjectionKind kind,
    String memberName,
    TypeRef type,
    MemberOrigin origin,
    String qualifier,
    TypeRef beanType,
    boolean multipleBeans) {}
